#!/usr/bin/env python3
"""
Builds faithful Arabic Clock v2.3.0 store-grade screenshots and icon variants
for the Just Apps landing page, matching Arabic-Clock-For-Android-'s real
MainActivity.java, ClockRenderer.java, and transparent home-screen widget.

Outputs:
  docs/assets/arabic-clock/icon.png (+ 512, 256, 192, 128, 64 variants)
  docs/assets/arabic-clock/widget.png (+ -780.webp, -400.webp)
  docs/assets/arabic-clock/customizer.png (+ -780.webp, -400.webp)
  docs/assets/arabic-clock/styles.png (+ -780.webp, -400.webp)
"""
from __future__ import annotations

import base64
import io
from pathlib import Path

from fontTools.ttLib import TTFont
import numpy as np
from PIL import Image, ImageDraw, ImageFilter, ImageFont

ROOT = Path(__file__).resolve().parent.parent
FONT_DIR = ROOT / "docs" / "assets" / "fonts"
SOURCE_ICON = ROOT / "design" / "source" / "AC-icon.png"
OUT_DIR = ROOT / "docs" / "assets" / "arabic-clock"
OUT_DIR.mkdir(parents=True, exist_ok=True)

# 3x reference canvas -> downsampled to 780x1688 and 400x866
W, H = 1170, 2532

# Arabic Clock v2.3.0 palette (from MainActivity.java & preview_checkerboard)
BG_MAIN = (16, 28, 32)           # #101C20
BG_SURFACE = (23, 39, 45)        # #17272D
BG_FIELD = (29, 48, 55)          # #1D3037
OUTLINE_SUBTLE = (46, 68, 76)    # #2E444C
GOLD = (220, 193, 138)           # #DCC18A
GOLD_SOFT = (180, 159, 114)      # #B49F72
GOLD_DIM = (58, 56, 46)          # #3A382E
WHITE = (255, 255, 255)
INK_PRIMARY = (238, 243, 244)    # #EEF3F4
INK_SECONDARY = (189, 204, 206)  # #BDCCCE
INK_HINT = (138, 156, 160)       # #8A9CA0
CHECK_A = (100, 119, 122)        # #64777A
CHECK_B = (113, 132, 136)        # #718488
BTN_DARK = (36, 56, 63)          # #24383F

# Pre-shaped Arabic glyph alpha masks from Arabic-Clock-For-Android- bundled fonts
# (janna_lt_bold.ttf, long_arabic.ttf, khebrat_musamim.ttf)
_SHAPED_ALPHA_B64: dict[str, str] = {
  "title_ar": "",
  "widget_h": "",
  "widget_m": "",
  "prev1_h": "",
  "prev1_m": "",
  "prev2_h": "",
  "prev2_m": ""
}

_FONT_BYTES_CACHE: dict[str, bytes] = {}


def _load_ttf_bytes(path: Path) -> bytes:
    key = str(path)
    if key not in _FONT_BYTES_CACHE:
        if path.suffix.lower() == ".woff2":
            buf = io.BytesIO()
            tt = TTFont(str(path))
            tt.flavor = None
            tt.save(buf)
            _FONT_BYTES_CACHE[key] = buf.getvalue()
        else:
            _FONT_BYTES_CACHE[key] = path.read_bytes()
    return _FONT_BYTES_CACHE[key]


def font(weight: int, size: int) -> ImageFont.FreeTypeFont:
    table = {
        400: "plus-jakarta-sans-latin-400-normal.woff2",
        500: "plus-jakarta-sans-latin-500-normal.woff2",
        600: "plus-jakarta-sans-latin-600-normal.woff2",
        700: "plus-jakarta-sans-latin-700-normal.woff2",
    }
    fname = table.get(weight, "plus-jakarta-sans-latin-500-normal.woff2")
    raw = _load_ttf_bytes(FONT_DIR / fname)
    return ImageFont.truetype(io.BytesIO(raw), size=size)


def shaped_mask(key: str) -> Image.Image:
    raw = base64.b64decode(_SHAPED_ALPHA_B64[key])
    return Image.open(io.BytesIO(raw)).convert("L")


def paste_tinted(
    canvas: Image.Image,
    mask: Image.Image,
    xy: tuple[int, int],
    color: tuple[int, int, int, int],
    outline_px: int = 0,
    outline_color: tuple[int, int, int, int] = (0, 0, 0, 255),
) -> None:
    x, y = xy
    if outline_px > 0:
        pad = outline_px + 4
        expanded = Image.new("L", (mask.width + pad * 2, mask.height + pad * 2), 0)
        expanded.paste(mask, (pad, pad))
        dilated = expanded.filter(ImageFilter.MaxFilter(outline_px * 2 + 1))
        dilated = dilated.filter(ImageFilter.GaussianBlur(radius=0.8))
        arr = np.array(dilated, dtype=np.float32) * (outline_color[3] / 255.0)
        rgba = np.zeros((dilated.height, dilated.width, 4), dtype=np.uint8)
        rgba[..., 0] = outline_color[0]
        rgba[..., 1] = outline_color[1]
        rgba[..., 2] = outline_color[2]
        rgba[..., 3] = np.clip(arr, 0, 255).astype(np.uint8)
        stroke_layer = Image.fromarray(rgba, "RGBA")
        canvas.paste(stroke_layer, (x - pad, y - pad), stroke_layer)

    arr_f = np.array(mask, dtype=np.float32) * (color[3] / 255.0)
    fill_rgba = np.zeros((mask.height, mask.width, 4), dtype=np.uint8)
    fill_rgba[..., 0] = color[0]
    fill_rgba[..., 1] = color[1]
    fill_rgba[..., 2] = color[2]
    fill_rgba[..., 3] = np.clip(arr_f, 0, 255).astype(np.uint8)
    fill_layer = Image.fromarray(fill_rgba, "RGBA")
    canvas.paste(fill_layer, (x, y), fill_layer)


# ---------------------------------------------------------------------------
# Icon generation
# ---------------------------------------------------------------------------

def build_icons() -> None:
    src = Image.open(SOURCE_ICON).convert("RGBA")
    master_size = 512
    ss = master_size * 4
    art_ss = src.resize((ss, ss), Image.Resampling.LANCZOS)
    mask_ss = Image.new("L", (ss, ss), 0)
    mdraw = ImageDraw.Draw(mask_ss)
    radius_ss = int(round(ss * 0.225))
    mdraw.rounded_rectangle((16, 16, ss - 17, ss - 17), radius=radius_ss, fill=255)

    rim_ss = Image.new("RGBA", (ss, ss), (0, 0, 0, 0))
    rdraw = ImageDraw.Draw(rim_ss)
    rdraw.rounded_rectangle(
        (18, 18, ss - 19, ss - 19),
        radius=radius_ss,
        outline=(220, 193, 138, 38),
        width=6,
    )

    framed_ss = Image.new("RGBA", (ss, ss), (0, 0, 0, 0))
    framed_ss.paste(art_ss, (0, 0), mask_ss)
    framed_ss = Image.alpha_composite(framed_ss, rim_ss)
    master = framed_ss.resize((master_size, master_size), Image.Resampling.LANCZOS)

    for s in (512, 256, 192, 128, 64):
        out = master if s == master_size else master.resize((s, s), Image.Resampling.LANCZOS)
        out.save(OUT_DIR / f"icon-{s}.png", optimize=True)
        print(f"  wrote icon-{s}.png")
    master.resize((192, 192), Image.Resampling.LANCZOS).save(OUT_DIR / "icon.png", optimize=True)
    print("  wrote icon.png")


# ---------------------------------------------------------------------------
# Shared UI chrome
# ---------------------------------------------------------------------------

def draw_status_bar(draw: ImageDraw.ImageDraw, time_str: str = "12:42") -> None:
    f_time = font(600, 38)
    draw.text((76, 44), time_str, font=f_time, fill=INK_PRIMARY)
    bx, by = W - 220, 54
    for i, bh in enumerate((12, 17, 22, 27)):
        x0 = bx + i * 13
        draw.rounded_rectangle((x0, by + 27 - bh, x0 + 8, by + 27), radius=2, fill=INK_PRIMARY)
    bat_x, bat_y = W - 134, 52
    draw.rounded_rectangle((bat_x, bat_y, bat_x + 56, bat_y + 28), radius=6, outline=INK_SECONDARY, width=2)
    draw.rounded_rectangle((bat_x + 5, bat_y + 5, bat_x + 45, bat_y + 23), radius=3, fill=INK_PRIMARY)
    draw.rounded_rectangle((bat_x + 58, bat_y + 9, bat_x + 62, bat_y + 19), radius=1, fill=INK_SECONDARY)


def draw_gesture_pill(draw: ImageDraw.ImageDraw) -> None:
    pw = 360
    px = (W - pw) // 2
    py = H - 46
    draw.rounded_rectangle((px, py, px + pw, py + 14), radius=7, fill=(238, 243, 244, 150))


def draw_checkerboard(img: Image.Image, box: tuple[int, int, int, int], radius: int = 44) -> None:
    x0, y0, x1, y1 = box
    cw, ch = x1 - x0, y1 - y0
    tile = 38
    yy = np.arange(ch)[:, None] // tile
    xx = np.arange(cw)[None, :] // tile
    parity = (xx + yy) % 2
    arr = np.zeros((ch, cw, 3), dtype=np.uint8)
    arr[parity == 0] = CHECK_A
    arr[parity == 1] = CHECK_B
    cb = Image.fromarray(arr, "RGB")

    mask = Image.new("L", (cw, ch), 0)
    mdraw = ImageDraw.Draw(mask)
    mdraw.rounded_rectangle((0, 0, cw - 1, ch - 1), radius=radius, fill=255)
    img.paste(cb, (x0, y0), mask)

    draw = ImageDraw.Draw(img, "RGBA")
    draw.rounded_rectangle(box, radius=radius, outline=(220, 193, 138, 70), width=3)


def draw_centered_text(draw: ImageDraw.ImageDraw, y: int, text: str, fnt: ImageFont.FreeTypeFont, fill) -> int:
    bb = draw.textbbox((0, 0), text, font=fnt)
    tw = bb[2] - bb[0]
    draw.text(((W - tw) // 2, y), text, font=fnt, fill=fill)
    return bb[3] - bb[1]


def draw_app_header(img: Image.Image, draw: ImageDraw.ImageDraw) -> int:
    # Matches MainActivity.java centered title: "الساعة العربية  ·  Arabic Clock" in #DCC18A
    ar_mask = shaped_mask("title_ar")
    f_en = font(700, 48)
    dot_text = "  ·  Arabic Clock"
    en_bbox = draw.textbbox((0, 0), dot_text, font=f_en)
    en_w = en_bbox[2] - en_bbox[0]
    total_w = ar_mask.width + en_w
    start_x = (W - total_w) // 2
    y_top = 132
    paste_tinted(img, ar_mask, (start_x, y_top + 4), (*GOLD, 255))
    draw.text((start_x + ar_mask.width, y_top), dot_text, font=f_en, fill=GOLD)

    draw_centered_text(draw, y_top + 82, "LIVE WIDGET PREVIEW", font(600, 29), INK_SECONDARY)
    return y_top + 132


def draw_switch_row(
    draw: ImageDraw.ImageDraw,
    y: int,
    label: str,
    checked: bool,
    enabled: bool = True,
) -> int:
    f_lbl = font(500, 37)
    fill_txt = INK_PRIMARY if enabled else INK_HINT
    draw.text((66, y + 12), label, font=f_lbl, fill=fill_txt)
    tw, th = 122, 68
    tx = W - 66 - tw
    ty = y + 4
    if checked:
        draw.rounded_rectangle((tx, ty, tx + tw, ty + th), radius=34, fill=(220, 193, 138, 72))
        draw.rounded_rectangle((tx, ty, tx + tw, ty + th), radius=34, outline=GOLD, width=3)
        kx = tx + tw - 58
        draw.ellipse((kx, ty + 8, kx + 52, ty + 60), fill=GOLD)
    else:
        track = (42, 61, 68) if enabled else (31, 46, 52)
        knob = INK_SECONDARY if enabled else (96, 112, 116)
        draw.rounded_rectangle((tx, ty, tx + tw, ty + th), radius=34, fill=track, outline=OUTLINE_SUBTLE, width=3)
        draw.ellipse((tx + 10, ty + 12, tx + 54, ty + 56), fill=knob)
    return y + 98


def draw_slider_row(
    draw: ImageDraw.ImageDraw,
    y: int,
    label: str,
    frac: float,
) -> int:
    f_lbl = font(500, 36)
    draw.text((66, y), label, font=f_lbl, fill=INK_PRIMARY)
    sy = y + 72
    x0, x1 = 76, W - 76
    xm = int(round(x0 + (x1 - x0) * frac))
    draw.rounded_rectangle((x0, sy - 6, x1, sy + 6), radius=6, fill=(45, 67, 75))
    draw.rounded_rectangle((x0, sy - 6, xm, sy + 6), radius=6, fill=GOLD)
    draw.ellipse((xm - 22, sy - 22, xm + 22, sy + 22), fill=GOLD)
    return sy + 56


def draw_spinner_box(draw: ImageDraw.ImageDraw, y: int, label: str, value: str) -> int:
    f_lbl = font(500, 35)
    f_val = font(600, 39)
    draw.text((66, y), label, font=f_lbl, fill=INK_SECONDARY)
    by = y + 52
    bh = 102
    draw.rounded_rectangle((66, by, W - 66, by + bh), radius=24, fill=BG_FIELD, outline=OUTLINE_SUBTLE, width=3)
    draw.text((100, by + 27), value, font=f_val, fill=INK_PRIMARY)
    cx = W - 122
    cy = by + bh // 2
    draw.polygon([(cx - 16, cy - 8), (cx + 16, cy - 8), (cx, cy + 12)], fill=GOLD)
    return by + bh + 34


def save_screen(img: Image.Image, stem: str) -> None:
    p780 = img.resize((780, 1688), Image.Resampling.LANCZOS)
    p400 = img.resize((400, 866), Image.Resampling.LANCZOS)
    p780.save(OUT_DIR / f"{stem}.png", optimize=True)
    p780.save(OUT_DIR / f"{stem}-780.webp", "WEBP", quality=88, method=6)
    p400.save(OUT_DIR / f"{stem}-400.webp", "WEBP", quality=86, method=6)
    print(f"  wrote {stem}.png + -780.webp + -400.webp")


# ---------------------------------------------------------------------------
# Screen 1: Transparent Home-Screen Widget in action (widget.*)
# ---------------------------------------------------------------------------

def build_widget_screen() -> None:
    yy = np.linspace(0.0, 1.0, H)[:, None]
    xx = np.linspace(0.0, 1.0, W)[None, :]
    r = 14 + 22 * (1.0 - yy) + 18 * np.exp(-((xx - 0.72) ** 2 + (yy - 0.24) ** 2) / 0.09)
    g = 28 + 34 * (1.0 - yy * 0.75) + 26 * np.exp(-((xx - 0.68) ** 2 + (yy - 0.26) ** 2) / 0.11)
    b = 34 + 38 * (1.0 - yy * 0.6) + 20 * np.exp(-((xx - 0.28) ** 2 + (yy - 0.68) ** 2) / 0.14)
    hill1 = 0.56 + 0.045 * np.sin(xx * 4.2 + 0.6) + 0.02 * np.cos(xx * 8.5)
    hill2 = 0.68 + 0.038 * np.cos(xx * 3.6 - 0.4)
    mask1 = (yy > hill1).astype(np.float32)
    mask2 = (yy > hill2).astype(np.float32)
    r = r * (1 - 0.26 * mask1) * (1 - 0.30 * mask2)
    g = g * (1 - 0.24 * mask1) * (1 - 0.28 * mask2)
    b = b * (1 - 0.20 * mask1) * (1 - 0.25 * mask2)

    rgb = np.stack([np.clip(r, 0, 255), np.clip(g, 0, 255), np.clip(b, 0, 255)], axis=-1).astype(np.uint8)
    img = Image.fromarray(rgb, "RGB")
    draw = ImageDraw.Draw(img, "RGBA")

    draw_status_bar(draw, "12:42")
    draw_centered_text(draw, 228, "Wed, Oct 28", font(500, 38), (238, 243, 244, 215))

    # 100% transparent Arabic Clock widget: ١٢ : ٤٢ with subtle dark outline
    mh = shaped_mask("widget_h")
    mm = shaped_mask("widget_m")
    gap_half = 56
    total_w = mh.width + gap_half * 2 + mm.width
    start_x = (W - total_w) // 2
    cy = 524

    paste_tinted(img, mh, (start_x, cy - mh.height // 2), (247, 241, 226, 255), outline_px=5, outline_color=(10, 18, 22, 195))
    paste_tinted(img, mm, (start_x + mh.width + gap_half * 2, cy - mm.height // 2), (247, 241, 226, 255), outline_px=5, outline_color=(10, 18, 22, 195))

    dot_cx = start_x + mh.width + gap_half
    dot_r = 17
    for dy in (-58, 58):
        draw.ellipse((dot_cx - dot_r - 5, cy + dy - dot_r - 5, dot_cx + dot_r + 5, cy + dy + dot_r + 5), fill=(10, 18, 22, 185))
        draw.ellipse((dot_cx - dot_r, cy + dy - dot_r, dot_cx + dot_r, cy + dy + dot_r), fill=(220, 193, 138, 255))

    iy = H - 430
    draw.ellipse((W // 2 - 36, iy, W // 2 - 20, iy + 16), fill=(255, 255, 255, 220))
    draw.ellipse((W // 2 - 4, iy, W // 2 + 12, iy + 16), fill=(255, 255, 255, 85))
    draw.ellipse((W // 2 + 28, iy, W // 2 + 44, iy + 16), fill=(255, 255, 255, 85))

    dock_y = H - 340
    slot_w = (W - 150) // 4
    icon_sz = 148
    ac_icon = Image.open(OUT_DIR / "icon-256.png").convert("RGBA").resize((icon_sz, icon_sz), Image.Resampling.LANCZOS)

    dock_specs = [
        ("Phone", (44, 78, 72)),
        ("Messages", (46, 68, 86)),
        ("Camera", (62, 66, 74)),
        ("Arabic Clock", None),
    ]
    for idx, (lbl, bg_col) in enumerate(dock_specs):
        ix = 75 + idx * slot_w + (slot_w - icon_sz) // 2
        if bg_col is None:
            img.paste(ac_icon, (ix, dock_y), ac_icon)
        else:
            draw.rounded_rectangle((ix, dock_y, ix + icon_sz, dock_y + icon_sz), radius=34, fill=(*bg_col, 230), outline=(255, 255, 255, 38), width=2)
            cx, cy_i = ix + icon_sz // 2, dock_y + icon_sz // 2
            if lbl == "Phone":
                draw.arc((cx - 34, cy_i - 34, cx + 34, cy_i + 34), start=35, end=215, fill=INK_PRIMARY, width=9)
            elif lbl == "Messages":
                draw.rounded_rectangle((cx - 36, cy_i - 28, cx + 36, cy_i + 24), radius=14, outline=INK_PRIMARY, width=7)
            elif lbl == "Camera":
                draw.rounded_rectangle((cx - 38, cy_i - 26, cx + 38, cy_i + 28), radius=14, outline=INK_PRIMARY, width=7)
                draw.ellipse((cx - 16, cy_i - 14, cx + 16, cy_i + 18), outline=GOLD, width=6)

    sp_y = H - 154
    draw.rounded_rectangle((96, sp_y, W - 96, sp_y + 78), radius=39, fill=(22, 36, 42, 205), outline=(255, 255, 255, 34), width=2)
    draw.ellipse((138, sp_y + 23, 170, sp_y + 55), outline=GOLD_SOFT, width=5)
    draw.line((166, sp_y + 51, 179, sp_y + 64), fill=GOLD_SOFT, width=5)
    draw.text((204, sp_y + 20), "Search apps & widgets", font=font(400, 32), fill=(189, 204, 206, 175))

    draw_gesture_pill(draw)
    save_screen(img, "widget")


# ---------------------------------------------------------------------------
# Screen 2: Single-Screen Live Customizer (customizer.*)
# ---------------------------------------------------------------------------

def build_customizer_screen() -> None:
    img = Image.new("RGB", (W, H), BG_MAIN)
    draw = ImageDraw.Draw(img, "RGBA")
    draw_status_bar(draw, "17:30")

    y = draw_app_header(img, draw)

    prev_box = (66, y, W - 66, y + 660)
    draw_checkerboard(img, prev_box, radius=42)

    mh = shaped_mask("prev1_h")
    mm = shaped_mask("prev1_m")
    gap_half = 48
    tw = mh.width + gap_half * 2 + mm.width
    px = (W - tw) // 2
    pcy = (prev_box[1] + prev_box[3]) // 2
    paste_tinted(img, mh, (px, pcy - mh.height // 2), (255, 255, 255, 255), outline_px=3, outline_color=(16, 28, 32, 110))
    paste_tinted(img, mm, (px + mh.width + gap_half * 2, pcy - mm.height // 2), (255, 255, 255, 255), outline_px=3, outline_color=(16, 28, 32, 110))
    dcx = px + mh.width + gap_half
    for dy in (-44, 44):
        draw.ellipse((dcx - 14, pcy + dy - 14, dcx + 14, pcy + dy + 14), fill=WHITE)

    y = prev_box[3] + 24
    draw_centered_text(draw, y, "100% transparent · checkerboard is preview only", font(400, 31), INK_SECONDARY)
    y += 58
    draw.line((66, y, W - 66, y), fill=(255, 255, 255, 34), width=3)
    y += 38

    draw.text((66, y), "Customize your widget", font=font(700, 44), fill=GOLD)
    y += 64
    draw.text(
        (66, y),
        "Changes apply to all placed widgets immediately.",
        font=font(400, 33),
        fill=INK_SECONDARY,
    )
    y += 72

    y = draw_spinner_box(draw, y, "Arabic font", "Long · Amiri")
    y = draw_spinner_box(draw, y, "Numeral width (dots stay unchanged)", "+15%")
    y = draw_slider_row(draw, y, "Font size · 96 sp", 0.34)
    y += 8
    y = draw_switch_row(draw, y, "Fill available widget space · HUGE", checked=False)
    y = draw_switch_row(draw, y, "Stack hours above minutes (no dots)", checked=False)
    y = draw_slider_row(draw, y, "Spacing · 14 dp", 0.35)

    draw_gesture_pill(draw)
    save_screen(img, "customizer")


# ---------------------------------------------------------------------------
# Screen 3: Stacked Mode, Font Outline & Color Controls (styles.*)
# ---------------------------------------------------------------------------

def build_styles_screen() -> None:
    img = Image.new("RGB", (W, H), BG_MAIN)
    draw = ImageDraw.Draw(img, "RGBA")
    draw_status_bar(draw, "8:45")

    y = draw_app_header(img, draw)

    prev_box = (66, y, W - 66, y + 660)
    draw_checkerboard(img, prev_box, radius=42)

    mh = shaped_mask("prev2_h")
    mm = shaped_mask("prev2_m")
    pcy = (prev_box[1] + prev_box[3]) // 2
    v_gap = 26
    total_h = mh.height + v_gap + mm.height
    top_y = pcy - total_h // 2
    paste_tinted(img, mh, ((W - mh.width) // 2, top_y), (*GOLD, 255), outline_px=7, outline_color=(0, 0, 0, 245))
    paste_tinted(img, mm, ((W - mm.width) // 2, top_y + mh.height + v_gap), (*GOLD, 255), outline_px=7, outline_color=(0, 0, 0, 245))

    y = prev_box[3] + 24
    draw_centered_text(draw, y, "100% transparent · checkerboard is preview only", font(400, 31), INK_SECONDARY)
    y += 58
    draw.line((66, y, W - 66, y), fill=(255, 255, 255, 34), width=3)
    y += 34

    y = draw_slider_row(draw, y, "Font opacity (0 = transparent, 100 = solid) · 96%", 0.96)
    y += 8
    y = draw_switch_row(draw, y, "Enable font outline", checked=True)
    y = draw_switch_row(draw, y, "Outline only · hollow numerals", checked=False)
    y = draw_slider_row(draw, y, "Outline thickness (scales with clock) · 3 dp", 0.36)
    y += 8

    draw.text((66, y), "Outline color · #000000", font=font(500, 35), fill=INK_SECONDARY)
    y += 52
    btn_w = (W - 132 - 36) // 3
    for i, (lbl, active) in enumerate([("Black", True), ("White", False), ("Custom", False)]):
        bx = 66 + i * (btn_w + 18)
        fill = GOLD_DIM if active else BTN_DARK
        border = GOLD if active else OUTLINE_SUBTLE
        txt_c = GOLD if active else INK_PRIMARY
        draw.rounded_rectangle((bx, y, bx + btn_w, y + 86), radius=20, fill=fill, outline=border, width=3)
        tb = draw.textbbox((0, 0), lbl, font=font(600, 35))
        draw.text((bx + (btn_w - (tb[2] - tb[0])) // 2, y + 22), lbl, font=font(600, 35), fill=txt_c)
    y += 116

    draw.text((66, y), "Text color · #DCC18A", font=font(500, 35), fill=INK_SECONDARY)
    y += 52
    btn4_w = (W - 132 - 48) // 4
    for i, (lbl, active) in enumerate([("White", False), ("Gold", True), ("Black", False), ("Custom", False)]):
        bx = 66 + i * (btn4_w + 16)
        fill = GOLD_DIM if active else BTN_DARK
        border = GOLD if active else OUTLINE_SUBTLE
        txt_c = GOLD if active else INK_PRIMARY
        draw.rounded_rectangle((bx, y, bx + btn4_w, y + 86), radius=20, fill=fill, outline=border, width=3)
        tb = draw.textbbox((0, 0), lbl, font=font(600, 34))
        draw.text((bx + (btn4_w - (tb[2] - tb[0])) // 2, y + 22), lbl, font=font(600, 34), fill=txt_c)
    y += 120

    draw.rounded_rectangle((66, y, W - 66, y + 112), radius=26, fill=GOLD)
    cta = "Add home-screen widget"
    cb = draw.textbbox((0, 0), cta, font=font(700, 38))
    draw.text(((W - (cb[2] - cb[0])) // 2, y + 32), cta, font=font(700, 38), fill=BG_MAIN)

    draw_gesture_pill(draw)
    save_screen(img, "styles")


def main() -> None:
    print("Building Arabic Clock v2.3.0 icons and screenshots...")
    build_icons()
    build_widget_screen()
    build_customizer_screen()
    build_styles_screen()
    print("Done.")


if __name__ == "__main__":
    main()
